package com.motionstudio.part2
import kotlin.math.*
data class Lut1D(val size:Int,val r:FloatArray,val g:FloatArray,val b:FloatArray){init{require(size>=2&&r.size==size&&g.size==size&&b.size==size);require((r+g+b).all{it.isFinite()&&it in 0f..1f})}}
data class Lut3D(val size:Int,val values:FloatArray){init{require(size>=2&&values.size==size*size*size*3);require(values.all{it.isFinite()&&it in 0f..1f})}}
object LutEngine { fun apply1D(src:FrameBuffer,lut:Lut1D,intensity:Float=1f):FrameBuffer{val q=intensity.coerceIn(0f,1f);val o=FrameBuffer(src.width,src.height);for(y in 0 until src.height)for(x in 0 until src.width){val c=src.get(x,y);val r=sample(lut.r,c.r);val g=sample(lut.g,c.g);val b=sample(lut.b,c.b);o.set(x,y,Rgba(c.r+(r-c.r)*q,c.g+(g-c.g)*q,c.b+(b-c.b)*q,c.a))};return o}
 fun apply3D(src:FrameBuffer,lut:Lut3D,intensity:Float=1f):FrameBuffer{val q=intensity.coerceIn(0f,1f);val o=FrameBuffer(src.width,src.height);for(y in 0 until src.height)for(x in 0 until src.width){val c=src.get(x,y);val z=lut.size-1;val fx=c.r*z;val fy=c.g*z;val fz=c.b*z;val x0=floor(fx).toInt();val y0=floor(fy).toInt();val z0=floor(fz).toInt();val x1=min(z,x0+1);val y1=min(z,y0+1);val z1=min(z,z0+1);val tx=fx-x0;val ty=fy-y0;val tz=fz-z0;val v={ix:Int,iy:Int,iz:Int,ch:Int->lut.values[((iz*lut.size+iy)*lut.size+ix)*3+ch]};fun tri(ch:Int):Float{val a=v(x0,y0,z0,ch)*(1-tx)+v(x1,y0,z0,ch)*tx;val b=v(x0,y1,z0,ch)*(1-tx)+v(x1,y1,z0,ch)*tx;val c0=v(x0,y0,z1,ch)*(1-tx)+v(x1,y0,z1,ch)*tx;val d=v(x0,y1,z1,ch)*(1-tx)+v(x1,y1,z1,ch)*tx;return (a*(1-ty)+b*ty)*(1-tz)+(c0*(1-ty)+d*ty)*tz};o.set(x,y,Rgba(c.r+(tri(0)-c.r)*q,c.g+(tri(1)-c.g)*q,c.b+(tri(2)-c.b)*q,c.a))};return o}
 fun stack(src:FrameBuffer,luts:List<Lut3D>,intensity:Float=1f):FrameBuffer=luts.fold(src){a,l->apply3D(a,l,intensity)}
 private fun sample(a:FloatArray,x:Float):Float{val p=x.coerceIn(0f,1f)*(a.size-1);val i=floor(p).toInt().coerceIn(0,a.size-2);return a[i]+(a[i+1]-a[i])*(p-i)} }
